import{_ as s,l as t,o as a,c as l,v as r,p as n,x as i,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"虚拟化类型 1 / 2","description":"","frontmatter":{"title":"虚拟化类型 1 / 2","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hypervisor-types.md","filePath":"cs/hypervisor-types.md","lastUpdated":1789023840000}'),h={name:"cs/hypervisor-types.md"};function u(E,e,M,m,_,B){const o=t("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="虚拟化类型-1-2" tabindex="-1">虚拟化类型 1 / 2 <a class="header-anchor" href="#虚拟化类型-1-2" aria-label="Permalink to &quot;虚拟化类型 1 / 2&quot;">​</a></h1><div class="epigraph"><p>第一类 hypervisor 直接跑在硬件上调度客户机；第二类作为宿主 OS 的进程，复用宿主驱动与调度，代价是多一层。</p><footer>—— 据 Popek and Goldberg 对虚拟机的要求；Tanenbaum 对类型的整理；[内核/用户](/cs/kernel-user) 为特权先修</footer></div><p><a href="/cs/kabi-module-signing">上一课</a>收口模块。<a href="/cs/kvm-qemu">KVM</a> 下一课才拆。缺口是 <strong>类型 1/2</strong>：谁拥有硬件、与容器不是一类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Popek：敏感指令必须陷入。类型 1：Xen、ESXi、Hyper-V bare。类型 2：VirtualBox 在 Linux 上。KVM 常被说成 1.5：Linux 即 hypervisor。缺口：I/O 谁提供（QEMU 用户态）。本课不把产品对比写成采购。</p><p><span class="marginnote">半虚拟化下一课。对象是特权与调度位置，不是云品牌。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>类型 1：VMM 选客户、处理 VM-exit。类型 2：宿主调度 QEMU 线程，KVM ioctl 进核。对照 <a href="/cs/cgroup-cpu-sched">cgroup</a>：类型 2 可套 cgroup。对照 <a href="/cs/dpdk-kernel-bypass">DPDK</a>：旁路是性能，不是 hypervisor 类型。</p>',8)),(a(),n(c,null,{default:i(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HW%5B%22%E7%A1%AC%E4%BB%B6%22%5D%20--%3E%20T1%5B%22%E7%B1%BB%E5%9E%8B1%20VMM%22%5D%0A%20%20T1%20--%3E%20G1%5B%22%E5%AE%A2%E6%88%B7%20OS%22%5D%0A%20%20HW%20--%3E%20HOST%5B%22%E5%AE%BF%E4%B8%BB%20OS%22%5D%0A%20%20HOST%20--%3E%20T2%5B%22%E7%B1%BB%E5%9E%8B2%20VMM%20%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20T2%20--%3E%20G2%5B%22%E5%AE%A2%E6%88%B7%20OS%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型决定驱动与延迟路径：类型 1 自己写设备模型或 Dom0；类型 2 借用宿主生态。Popek 条件解释为何需要硬件辅助（下一课 VMX）。不要写成量化多租户。与 <a href="/cs/lsm-selinux">LSM</a>：宿主 LSM 管类型 2 的 QEMU。</p><p>安全边界：类型 2 宿主被攻则客户全完。</p><p>实现上：Popek 的敏感指令在 x86 上靠 VMX 补齐历史缺口。类型 2 的设备模型丰富，类型 1 要把驱动放在特权分区或用户 QEMU。KVM 让 Linux 调度器直接管 vCPU 线程。 读法上只引用<a href="/cs/kabi-module-signing">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>虚拟化类型 1 / 2</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 nested 标志。不保证微内核 hypervisor 的归类争论。下一课 KVM 与 QEMU 分工。</p><p>版本字段会变，课序钉的是机制对象「虚拟化类型 1 / 2」，不是某一主线内核的结构体名。 后课默认：VMM 可以是裸机或宿主进程。KVM 进核、QEMU 设备模型，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型 1 直接管硬件；类型 2 活在宿主 OS。</li><li>Linux+KVM 是内核作 VMM、用户作设备。</li><li>KVM/QEMU 是下一课。</li><li>出处：Popek/Goldberg；Tanenbaum <em>MOS</em>；KVM 概述。</li></ul>',11))])}const T=s(h,[["render",u]]);export{f as __pageData,T as default};
